@import "@fontsource-variable/archivo/wdth.css";

/* Light (faithful): warm paper (#f7f7f5) under a pale steel-blue wash (#c4d5e7), pure black
   text, an electric blue (#0e76ff) for marks and arrow boxes, and a mid blue (#2f66b3) that
   carries the big gradient bands between light and dark screens. */
:root {
  --background: #f7f7f5;
  --foreground: #000000;
  --card: #efefed;
  --card-foreground: #000000;
  --popover: #f7f7f5;
  --popover-foreground: #000000;
  --primary: #0e76ff;
  --primary-foreground: #f3f3f3;
  --secondary: #dfdfdd;
  --secondary-foreground: #000000;
  --muted: #ebebe9;
  --muted-foreground: #666666;
  --accent: #c4d5e7;
  --accent-foreground: #000000;
  --destructive: #d92d20;
  --destructive-foreground: #f3f3f3;
  --border: rgb(0 0 0 / 15%);
  --input: rgb(0 0 0 / 15%);
  --ring: #0e76ff;
  --highlight: #0e76ff;
  --highlight-foreground: #f3f3f3;
  --glow: #2f66b3;
  --chart-1: #0e76ff;
  --chart-2: #2f66b3;
  --chart-3: #c4d5e7;
  --chart-4: #0a2a57;
  --chart-5: #666666;
  --sidebar: #efefed;
  --sidebar-foreground: #000000;
  --sidebar-primary: #0e76ff;
  --sidebar-primary-foreground: #f3f3f3;
  --sidebar-accent: #c4d5e7;
  --sidebar-accent-foreground: #000000;
  --sidebar-border: rgb(0 0 0 / 15%);
  --sidebar-ring: #0e76ff;

  --typeface-body: "Archivo Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Archivo Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0rem;
  --page-width: 90rem;
  --page-gutter: clamp(1rem, 0.5rem + 1.6vw, 1.75rem);
  --section-y: clamp(4.5rem, 3rem + 5vw, 7.5rem);
}

/* Dark: pure black with off-white text and a slightly lifted panel (#0a0a0a); the pale wash
   becomes a deep navy, the blues stay. */
.dark {
  --background: #000000;
  --foreground: #f3f3f3;
  --card: #0a0a0a;
  --card-foreground: #f3f3f3;
  --popover: #111113;
  --popover-foreground: #f3f3f3;
  --primary: #0e76ff;
  --primary-foreground: #f3f3f3;
  --secondary: #1d1d20;
  --secondary-foreground: #f3f3f3;
  --muted: #141416;
  --muted-foreground: #9b9b9b;
  --accent: #0b1f3f;
  --accent-foreground: #f3f3f3;
  --destructive: #f04438;
  --destructive-foreground: #f3f3f3;
  --border: rgb(243 243 243 / 15%);
  --input: rgb(243 243 243 / 18%);
  --ring: #0e76ff;
  --highlight: #0e76ff;
  --highlight-foreground: #f3f3f3;
  --glow: #2f66b3;
  --chart-1: #0e76ff;
  --chart-2: #5b8fd6;
  --chart-3: #c4d5e7;
  --chart-4: #2f66b3;
  --chart-5: #9b9b9b;
  --sidebar: #0a0a0a;
  --sidebar-foreground: #f3f3f3;
  --sidebar-primary: #0e76ff;
  --sidebar-primary-foreground: #f3f3f3;
  --sidebar-accent: #0b1f3f;
  --sidebar-accent-foreground: #f3f3f3;
  --sidebar-border: rgb(243 243 243 / 15%);
  --sidebar-ring: #0e76ff;
}
